// OpenAI Responses API çıktısını doğrula;
// nihai sentez rolleri ile tekrarları kaldır
// ve Planner sözleşmesine dönüştür.

const response = $input.first().json;
const source = $('Validate Planner Input').first().json;

const question = source.question;

// Önceki node'da model taşınıyorsa onu kullan.
// Yoksa varsayılan olarak gpt-5-mini kabul et.
const model =
  source.model ??
  source.openaiModel ??
  'gpt-5-mini';

// OpenAI Responses API içindeki output_text değerini bul.
const content = response?.output
  ?.flatMap((item) => Array.isArray(item?.content) ? item.content : [])
  ?.find((item) => item?.type === 'output_text')
  ?.text;

if (typeof content !== 'string' || !content.trim()) {
  throw new Error(
    'Planner yanıt hatası: OpenAI response.output içinde output_text döndürmedi.'
  );
}

let plan;

try {
  plan = JSON.parse(content);
} catch (error) {
  throw new Error(
    `Planner ayrıştırma hatası: OpenAI geçerli JSON döndürmedi (${error.message}).`
  );
}

if (!Array.isArray(plan.agents) || plan.agents.length === 0) {
  throw new Error(
    'Planner doğrulama hatası: agents boş olmayan bir dizi olmalıdır.'
  );
}

const allowedComplexities = new Set(['low', 'medium', 'high']);

const complexity = allowedComplexities.has(plan.complexity)
  ? plan.complexity
  : null;

if (!complexity) {
  throw new Error(
    'Planner doğrulama hatası: complexity low, medium veya high olmalıdır.'
  );
}

const forbiddenRolePattern =
  /(judge|jüri|hakem|sentez|sentezleyici|rapor yazarı|doküman yazarı|sonuçlandırma|sonuç yazarı|nihai (cevap|yanıt|sonuç)|final (answer|response|report)|baş editör|genel editör|özet uzmanı|özetleyici|özet[/ ]sonuç|öneri koordinatörü)/i;

const forbiddenTaskPattern =
  /(tüm (uzman|agent|yanıt|cevap).{0,40}(birleştir|sentezle|özetle)|nihai (cevabı|yanıtı|sonucu|raporu) (yaz|oluştur|hazırla)|final (answer|response|report))/i;

const genericRolePattern =
  /^(uzman|expert|assistant|agent|analist|genel analist|soruya özel uzman)(\s*\d+)?$/i;

const normalizeText = (value) =>
  value
    .toLocaleLowerCase('tr-TR')
    .replace(/[^a-z0-9çğıöşü]+/gi, ' ')
    .trim();

const seenRoles = new Set();
const seenTasks = new Set();
const accepted = [];

for (const candidate of plan.agents) {
  if (accepted.length >= (complexity === 'low' ? 1 : 4)) break;

  const role =
    typeof candidate?.role === 'string'
      ? candidate.role.trim()
      : '';

  const task =
    typeof candidate?.task === 'string'
      ? candidate.task.trim()
      : '';

  if (!role || !task) continue;

  if (
    forbiddenRolePattern.test(role) ||
    forbiddenTaskPattern.test(task) ||
    genericRolePattern.test(role)
  ) {
    continue;
  }

  const roleKey = normalizeText(role);
  const taskKey = normalizeText(task);

  if (!roleKey || !taskKey) continue;

  if (
    seenRoles.has(roleKey) ||
    seenTasks.has(taskKey)
  ) {
    continue;
  }

  seenRoles.add(roleKey);
  seenTasks.add(taskKey);

  accepted.push({
    role,
    task,
  });
}

if (accepted.length === 0) {
  accepted.push({
    role: 'Konu Alanı Analisti',
    task:
      'Asıl sorunun doğrudan cevaplanması için gerekli temel olguları, ölçütleri ve belirsizlikleri bağımsız olarak incele.',
  });
}

const agents = accepted.map((agent, index) => ({
  agent_id: index + 1,
  role: agent.role,
  task: agent.task,
}));

const questionType =
  typeof plan.question_type === 'string' &&
  plan.question_type.trim()
    ? plan.question_type.trim()
    : 'genel';

return [
  {
    json: {
      question,
      model,
      questionType,
      complexity,
      agentCount: agents.length,
      agents,
    },
  },
];
